define(['jquery', 'Magento_Ui/js/modal/modal', 'Magento_Customer/js/customer-data'], function($, modal, customerData) {
    'use strict';
    return {
        modalWindow: null,
        createPopUp: function(element) {
            $('#top-cart-btn-checkout').on('click', function(event) {
                $('#top-cart-btn-checkout').addClass('prodceed-btn');
                var customer = customerData.get('customer')();
                if (!customer.firstname) {
                    $("#customer-account-link-id").trigger('click');
                }
                if (customer.firstname) {
                    location.href = window.isAddressExist > 0 ? window.checkout.checkoutUrl + '#payment' : window.checkout.checkoutUrl + '#shipping';
                }
            });
        },
        showModal: function() {
            $(this.modalWindow).modal('openModal').trigger('contentUpdated');
        }
    };
});